helpers.cm_list_copy:
function cm_list_copy(xs)
  local r = {}
  for i = 1, #xs do r[i] = xs[i] end
  return r
end

helpers.cm_list_new:
function cm_list_new(n, v)
  if n < 0 then error('negative length') end
  local r = {}
  for i = 1, n do r[i] = v end
  return r
end

helpers.cm_read_lf:
function cm_read_lf()
  local r = {}
  for i = 1, cm_read_int() do r[i] = cm_read_float() end
  return r
end

helpers.cm_read_li:
function cm_read_li()
  local r = {}
  for i = 1, cm_read_int() do r[i] = cm_read_int() end
  return r
end

helpers.cm_s_at:
function cm_s_at(s, i)
  if i < 0 or i >= utf8.len(s) then error("string index out of range") end
  return utf8.codepoint(s, utf8.offset(s, i + 1))
end

helpers.cm_s_chr:
function cm_s_chr(c)
  if c < 0 or c > 0x10FFFF or (c >= 0xD800 and c <= 0xDFFF) then error("not a Unicode scalar value") end
  return utf8.char(c)
end

helpers.cm_s_codes:
function cm_s_codes(s)
  local t = {}
  for _, c in utf8.codes(s) do t[#t + 1] = string.format("%d", c) end
  return table.concat(t, " ")
end

helpers.cm_s_cps:
function cm_s_cps(s)
  local t = {}
  for _, c in utf8.codes(s) do t[#t + 1] = c end
  return t
end

helpers.cm_s_ord:
function cm_s_ord(s)
  if utf8.len(s) ~= 1 then error("ord of a string whose length is not 1") end
  return utf8.codepoint(s, 1)
end

helpers.cm_s_slice:
function cm_s_slice(s, a, b)
  local n = utf8.len(s)
  local lo, hi = cm_s_clamp(a, n), cm_s_clamp(b, n)
  if lo >= hi then return "" end
  return string.sub(s, utf8.offset(s, lo + 1), utf8.offset(s, hi + 1) - 1)
end
